package com.example.dacn.service.Impl;
import com.example.dacn.dto.request.*; import com.example.dacn.dto.response.*; import com.example.dacn.entity.*; import com.example.dacn.exception.*; import com.example.dacn.repository.*; import com.example.dacn.service.RestaurantWorkforceService;
import lombok.RequiredArgsConstructor; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal; import java.time.*; import java.util.*; import java.util.stream.Collectors;

@Service @RequiredArgsConstructor @Transactional
public class RestaurantWorkforceServiceImpl implements RestaurantWorkforceService {
 private final RestaurantRepository restaurants; private final RestaurantEmployeeRepository employees; private final EmployeeSalaryHistoryRepository salaries;
 private final EmploymentTerminationHistoryRepository terminations; private final RestaurantRentCostRepository rents; private final RestaurantRentCostHistoryRepository rentHistory;
 private Restaurant restaurant(Long id){return restaurants.findById(id).orElseThrow(()->new AppException(ErrorCode.RESTAURANT_NOT_FOUND));}
 private Account admin(){Object p=SecurityContextHolder.getContext().getAuthentication().getPrincipal(); if(p instanceof Account a)return a; throw new AppException(ErrorCode.UNAUTHENTICATED);}
 private RestaurantEmployee employee(Long rid,Long id){RestaurantEmployee e=employees.findById(id).orElseThrow(()->new AppException(ErrorCode.INVALID_REQUEST)); if(!e.getRestaurant().getId().equals(rid))throw new AppException(ErrorCode.UNAUTHORIZED); return e;}
 private RestaurantEmployeeResponse map(RestaurantEmployee e){return RestaurantEmployeeResponse.builder().id(e.getId()).employeeCode(e.getEmployeeCode()).fullName(e.getFullName()).phoneNumber(e.getPhoneNumber()).position(e.getPosition()).restaurantId(e.getRestaurant().getId()).restaurantName(e.getRestaurant().getName()).startDate(e.getStartDate()).monthlySalary(e.getMonthlySalary()).status(e.getStatus()).note(e.getNote()).terminationRequestedAt(e.getTerminationRequestedAt()).terminationEffectiveAt(e.getTerminationEffectiveAt()).terminationReason(e.getTerminationReason()).build();}
 @Transactional(readOnly=true) public List<RestaurantEmployeeResponse> search(Long rid,String q,EmployeePosition p,EmploymentStatus s){restaurant(rid); return employees.search(rid,q==null||q.isBlank()?null:q.trim(),p,s).stream().map(this::map).toList();}
 public RestaurantEmployeeResponse create(Long rid,RestaurantEmployeeRequest r){RestaurantEmployee e=RestaurantEmployee.builder().employeeCode("FCA-"+UUID.randomUUID().toString().substring(0,8).toUpperCase()).fullName(r.getFullName().trim()).phoneNumber(r.getPhoneNumber().trim()).position(r.getPosition()).restaurant(restaurant(rid)).startDate(r.getStartDate()).monthlySalary(r.getMonthlySalary()).status(EmploymentStatus.ACTIVE).note(r.getNote()).build(); employees.save(e); salaries.save(EmployeeSalaryHistory.builder().employee(e).oldSalary(r.getMonthlySalary()).newSalary(r.getMonthlySalary()).effectiveFrom(r.getStartDate()).performedBy(admin()).build()); return map(e);}
 public RestaurantEmployeeResponse update(Long rid,Long id,RestaurantEmployeeRequest r){RestaurantEmployee e=employee(rid,id); e.setFullName(r.getFullName().trim());e.setPhoneNumber(r.getPhoneNumber().trim());e.setPosition(r.getPosition());e.setStartDate(r.getStartDate());e.setNote(r.getNote()); if(e.getMonthlySalary().compareTo(r.getMonthlySalary())!=0) recordSalary(e,r.getMonthlySalary(),LocalDate.now()); return map(e);}
 private void recordSalary(RestaurantEmployee e,BigDecimal value,LocalDate from){salaries.save(EmployeeSalaryHistory.builder().employee(e).oldSalary(e.getMonthlySalary()).newSalary(value).effectiveFrom(from).performedBy(admin()).build());e.setMonthlySalary(value);}
 public RestaurantEmployeeResponse changeSalary(Long rid,Long id,EmployeeSalaryRequest r){RestaurantEmployee e=employee(rid,id);recordSalary(e,r.getSalary(),r.getEffectiveFrom());return map(e);}
 public RestaurantEmployeeResponse requestTermination(Long rid,Long id,EmployeeTerminationRequest r){RestaurantEmployee e=employee(rid,id);if(e.getStatus()!=EmploymentStatus.ACTIVE)throw new AppException(ErrorCode.INVALID_REQUEST);LocalDateTime now=LocalDateTime.now(),due=now.plusDays(3);e.setStatus(EmploymentStatus.PENDING_TERMINATION);e.setTerminationRequestedAt(now);e.setTerminationEffectiveAt(due);e.setTerminationReason(r.getReason().trim());terminations.save(EmploymentTerminationHistory.builder().employee(e).action("REQUESTED").reason(e.getTerminationReason()).effectiveAt(due).performedBy(admin()).build());return map(e);}
 public RestaurantEmployeeResponse cancelTermination(Long rid,Long id){RestaurantEmployee e=employee(rid,id);if(e.getStatus()!=EmploymentStatus.PENDING_TERMINATION)throw new AppException(ErrorCode.INVALID_REQUEST);terminations.save(EmploymentTerminationHistory.builder().employee(e).action("CANCELLED").reason(e.getTerminationReason()).effectiveAt(e.getTerminationEffectiveAt()).performedBy(admin()).build());e.setStatus(EmploymentStatus.ACTIVE);e.setTerminationRequestedAt(null);e.setTerminationEffectiveAt(null);e.setTerminationReason(null);return map(e);}
 @Transactional(readOnly=true) public List<EmployeeSalaryHistoryResponse> salaryHistory(Long rid,Long id){employee(rid,id);return salaries.findByEmployeeIdAndEffectiveFromLessThanEqualOrderByEffectiveFromDesc(id,LocalDate.of(9999,12,31)).stream().map(h->EmployeeSalaryHistoryResponse.builder().oldSalary(h.getOldSalary()).newSalary(h.getNewSalary()).effectiveFrom(h.getEffectiveFrom()).recordedAt(h.getCreatedAt()).performedByAccountId(h.getPerformedBy().getId()).build()).toList();}
 @Transactional(readOnly=true) public List<EmploymentTerminationHistoryResponse> terminationHistory(Long rid,Long id){employee(rid,id);return terminations.findByEmployeeIdOrderByCreatedAtDesc(id).stream().map(h->EmploymentTerminationHistoryResponse.builder().action(h.getAction()).reason(h.getReason()).effectiveAt(h.getEffectiveAt()).recordedAt(h.getCreatedAt()).performedByAccountId(h.getPerformedBy().getId()).build()).toList();}
 public void finalizeDueTerminations(){for(RestaurantEmployee e:employees.findByStatusAndTerminationEffectiveAtLessThanEqual(EmploymentStatus.PENDING_TERMINATION,LocalDateTime.now())){Account actor=terminations.findFirstByEmployeeIdAndActionOrderByCreatedAtDesc(e.getId(),"REQUESTED").map(EmploymentTerminationHistory::getPerformedBy).orElseThrow(()->new AppException(ErrorCode.INVALID_REQUEST));e.setStatus(EmploymentStatus.TERMINATED);terminations.save(EmploymentTerminationHistory.builder().employee(e).action("FINALIZED").reason(e.getTerminationReason()).effectiveAt(e.getTerminationEffectiveAt()).performedBy(actor).build());}}
 public void saveRent(Long rid,RestaurantRentRequest r){Account actor=admin();RestaurantRentCost c=rents.findByRestaurantIdAndYearAndMonth(rid,r.getYear(),r.getMonth()).orElseGet(()->RestaurantRentCost.builder().restaurant(restaurant(rid)).year(r.getYear()).month(r.getMonth()).build());BigDecimal old=c.getAmount();c.setAmount(r.getAmount());c.setUpdatedBy(actor);rents.save(c);rentHistory.save(RestaurantRentCostHistory.builder().rentCost(c).oldAmount(old).newAmount(r.getAmount()).performedBy(actor).build());}
 @Transactional(readOnly=true) public RestaurantCostReportResponse report(Long rid,int year,int month){restaurant(rid);YearMonth ym=YearMonth.of(year,month);LocalDate start=ym.atDay(1),end=ym.atEndOfMonth();List<RestaurantEmployee> included=employees.findByRestaurantIdOrderByFullNameAsc(rid).stream().filter(e->!e.getStartDate().isAfter(end)&&(e.getTerminationEffectiveAt()==null||e.getTerminationEffectiveAt().toLocalDate().isAfter(start))).toList();Map<String,Long> counts=included.stream().collect(Collectors.groupingBy(e->e.getPosition().name(),LinkedHashMap::new,Collectors.counting()));Map<String,BigDecimal> byRole=new LinkedHashMap<>();for(RestaurantEmployee e:included){BigDecimal salary=salaries.findByEmployeeIdAndEffectiveFromLessThanEqualOrderByEffectiveFromDesc(e.getId(),end).stream().findFirst().map(EmployeeSalaryHistory::getNewSalary).orElse(e.getMonthlySalary());byRole.merge(e.getPosition().name(),salary,BigDecimal::add);}BigDecimal total=byRole.values().stream().reduce(BigDecimal.ZERO,BigDecimal::add),ship=byRole.getOrDefault(EmployeePosition.SHIPPER.name(),BigDecimal.ZERO),rent=rents.findByRestaurantIdAndYearAndMonth(rid,year,month).map(RestaurantRentCost::getAmount).orElse(BigDecimal.ZERO);return RestaurantCostReportResponse.builder().restaurantId(rid).year(year).month(month).activeEmployees(included.size()).activeShippers(counts.getOrDefault(EmployeePosition.SHIPPER.name(),0L)).employeeCountByPosition(counts).salaryByPosition(byRole).shipperSalary(ship).totalSalary(total).rentCost(rent).totalPersonnelCost(total).totalManagedOperatingCost(total.add(rent)).includedEmployees(included.stream().map(this::map).toList()).build();}
}
